import { useEffect, useMemo, useState } from 'react';

import {
  useCurrentPage,
  usePageFilterApplied,
  usePageFilterStatus,
} from 'hooks';
import { getViewtype, normalizeFilters } from 'utils/filter';
import { generateHash } from 'utils/pageCache/generateHash';

export const usePageHashInput = (
  pageName: string,
): { hashInput: string | null } => {
  const { currentPage } = useCurrentPage();
  const { applied } = usePageFilterApplied(currentPage);
  const { isLoading: filtersLoading } = usePageFilterStatus(currentPage);

  const activeFilters = useMemo(() => normalizeFilters(applied), [applied]);

  const viewtype = useMemo(
    () => getViewtype(activeFilters?.country),
    [activeFilters?.country],
  );

  const hashInput = useMemo(() => {
    if (filtersLoading || !activeFilters) return null;

    return JSON.stringify({
      pageName,
      viewtype,
      filters: activeFilters,
    });
  }, [pageName, viewtype, activeFilters, filtersLoading]);

  return { hashInput };
};

export const useResolvedPageHash = (
  pageName: string,
): {
  pageHash: string | null;
  setPageHash: React.Dispatch<React.SetStateAction<string | null>>;
} => {
  const { hashInput } = usePageHashInput(pageName);
  const [pageHash, setPageHash] = useState<string | null>(null);

  useEffect(() => {
    if (!hashInput) {
      setPageHash(null);
      return;
    }

    let cancelled = false;
    generateHash(hashInput).then((hash) => {
      if (!cancelled) setPageHash(hash);
    });
    return () => {
      cancelled = true;
    };
  }, [hashInput]);

  return { pageHash, setPageHash };
};
